Boolean out_q_insert( Out_Q out_q , Out_Func out_func , UInt32 t_offset ,  UInt32 t_on , UInt32 t_off  , UInt8 pulse )
{	
	Boolean ret = FALSE ;
	
	Out_Q_Node *out_q_node = (Out_Q_Node*)fifo_remove( out_q->fifo_free ); 	
			
	insert_in_pennding:
	{
		if( out_q_node )
		{
			out_q_node->req_done = FALSE ; 
			out_q_node->do_reset = FALSE ;

			fifo_insert( out_q->fifo_exec , (Fifo_Node*) out_q_node ); 
									
			out_set( out_q_node->out , out_func ); 
	
			out_exec_start( out_q_node->out ,t_offset , t_on , t_off , pulse );
	
			ret = TRUE ;
		}
		else
		{
			out_q_node = out_q_free_create(); 
				        
            if( out_q_node ) goto insert_in_pennding ; 

		};
	};
					
	return ret ;
}

